from hypothesis import given, strategies as st
import pytest


def get_all_subclasses(cls):
    """Recursively finds and returns a :class:`list` of all types
    inherited from *cls*.

    >>> class A(object):
    ...     pass
    ...
    >>> class B(A):
    ...     pass
    ...
    >>> class C(B):
    ...     pass
    ...
    >>> class D(A):
    ...     pass
    ...
    >>> [t.__name__ for t in get_all_subclasses(A)]
    ['B', 'D', 'C']
    >>> [t.__name__ for t in get_all_subclasses(B)]
    ['C']

    """
    from collections import deque
    try:
        to_check = deque(cls.__subclasses__())
    except (AttributeError, TypeError):
        raise TypeError('expected type object, not %r' % cls)
    seen, ret = (set(), [])
    while to_check:
        cur = to_check.popleft()
        if cur in seen:
            continue
        ret.append(cur)
        seen.add(cur)
        to_check.extend(cur.__subclasses__())
    return ret


@given(cls=st.sampled_from([object, int, float, str, bytes, list, dict, set, tuple, bool, Exception, ValueError, TypeError, RuntimeError, OSError, BaseException]))
def test_type_postcondition_returns_list(cls):
    assert isinstance(get_all_subclasses(cls), list)


@given(cls=st.sampled_from([object, int, float, str, bytes, list, dict, set, tuple, bool, Exception, ValueError, TypeError, RuntimeError, OSError, BaseException]))
def test_type_postcondition_all_types(cls):
    assert all(isinstance(t, type) for t in get_all_subclasses(cls))


@given(cls=st.sampled_from([object, int, float, str, bytes, list, dict, set, tuple, bool, Exception, ValueError, TypeError, RuntimeError, OSError, BaseException]))
def test_value_postcondition_cls_not_in_result(cls):
    assert cls not in get_all_subclasses(cls)


@given(cls=st.sampled_from([object, int, float, str, bytes, list, dict, set, tuple, bool, Exception, ValueError, TypeError, RuntimeError, OSError, BaseException]))
def test_value_postcondition_no_duplicates(cls):
    result = get_all_subclasses(cls)
    assert len(result) == len(set(result))


@given(cls=st.sampled_from([object, int, float, str, bytes, list, dict, set, tuple, bool, Exception, ValueError, TypeError, RuntimeError, OSError, BaseException]))
def test_metamorphic_subclass_subset(cls):
    all_subs = get_all_subclasses(cls)
    for sub in all_subs:
        assert set(get_all_subclasses(sub)).issubset(set(all_subs))


@given(cls=st.sampled_from([object, int, float, str, bytes, list, dict, set, tuple, bool, Exception, ValueError, TypeError, RuntimeError, OSError, BaseException]))
def test_invariant_preservation_all_subclasses(cls):
    assert all(issubclass(t, cls) for t in get_all_subclasses(cls))


@given(cls=st.sampled_from([object, int, float, str, bytes, list, dict, set, tuple, bool, Exception, ValueError, TypeError, RuntimeError, OSError, BaseException]))
def test_totality(cls):
    get_all_subclasses(cls)

