from hypothesis import given, strategies as st
import pytest
from collections.abc import Iterable


def flatten_iter(iterable):
    """``flatten_iter()`` yields all the elements from *iterable* while
    collapsing any nested iterables.

    >>> nested = [[1, 2], [[3], [4, 5]]]
    >>> list(flatten_iter(nested))
    [1, 2, 3, 4, 5]
    """
    from collections.abc import Iterable
    for item in iterable:
        if isinstance(item, Iterable) and (not isinstance(item, (str, bytes))):
            yield from flatten_iter(item)
        else:
            yield item


@given(iterable=st.recursive(st.one_of(st.integers(), st.floats(allow_nan=False), st.text(), st.booleans(), st.none()), lambda children: st.lists(children, max_size=5), max_leaves=20))
def test_idempotence(iterable):
    first_pass = list(flatten_iter(iterable))
    assert list(flatten_iter(first_pass)) == first_pass


@given(iterable=st.recursive(st.one_of(st.integers(), st.floats(allow_nan=False), st.text(), st.booleans(), st.none()), lambda children: st.lists(children, max_size=5), max_leaves=20))
def test_invariant_preservation(iterable):
    result = list(flatten_iter(iterable))
    # The multiset of leaf elements is stable: sorting twice gives the same result
    assert sorted(result) == sorted(result)
    # Count leaf elements recursively to verify length
    def count_leaves(obj):
        if isinstance(obj, Iterable) and not isinstance(obj, (str, bytes)):
            return sum(count_leaves(item) for item in obj)
        return 1
    expected_len = count_leaves(iterable)
    assert len(result) == expected_len


@given(
    a=st.recursive(st.one_of(st.integers(), st.floats(allow_nan=False), st.text(), st.booleans(), st.none()), lambda children: st.lists(children, max_size=5), max_leaves=10),
    b=st.recursive(st.one_of(st.integers(), st.floats(allow_nan=False), st.text(), st.booleans(), st.none()), lambda children: st.lists(children, max_size=5), max_leaves=10),
)
def test_metamorphic(a, b):
    combined = list(flatten_iter([a, b]))
    separate = list(flatten_iter(a)) + list(flatten_iter(b))
    assert combined == separate


@given(iterable=st.recursive(st.one_of(st.integers(), st.floats(allow_nan=False), st.text(), st.booleans(), st.none()), lambda children: st.lists(children, max_size=5), max_leaves=20))
def test_type_postcondition(iterable):
    for item in flatten_iter(iterable):
        # Every yielded element must be a non-list leaf:
        # either not Iterable at all, or a str/bytes (which are treated as leaves)
        is_leaf = not isinstance(item, Iterable) or isinstance(item, (str, bytes))
        assert is_leaf, f"Expected a leaf element but got: {item!r}"


@given(iterable=st.recursive(st.one_of(st.integers(), st.floats(allow_nan=False), st.text(), st.booleans(), st.none()), lambda children: st.lists(children, max_size=5), max_leaves=20))
def test_totality(iterable):
    # Should not raise for any finitely nested, non-circular structure
    result = list(flatten_iter(iterable))
    assert result is not None

from hypothesis import given, strategies as st
import pytest


def subdict(d, keep=None, drop=None):
    """Compute the "subdictionary" of a dict, *d*.

    A subdict is to a dict what a subset is a to set. If *A* is a
    subdict of *B*, that means that all keys of *A* are present in
    *B*.

    Returns a new dict with any keys in *drop* removed, and any keys
    in *keep* still present, provided they were in the original
    dict. *keep* defaults to all keys, *drop* defaults to empty, so
    without one of these arguments, calling this function is
    equivalent to calling ``dict()``.

    >>> from pprint import pprint as pp
    >>> pp(subdict({'a': 1, 'b': 2}))
    {'a': 1, 'b': 2}
    >>> subdict({'a': 1, 'b': 2, 'c': 3}, drop=['b', 'c'])
    {'a': 1}
    >>> pp(subdict({'a': 1, 'b': 2, 'c': 3}, keep=['a', 'c']))
    {'a': 1, 'c': 3}

    """
    if keep is None:
        keep = d.keys()
    if drop is None:
        drop = []
    keys = set(keep) - set(drop)
    return type(d)([(k, v) for k, v in d.items() if k in keys])


@given(
    d=st.dictionaries(keys=st.one_of(st.text(), st.integers()), values=st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.none())),
    keep=st.one_of(st.none(), st.lists(st.one_of(st.text(), st.integers()))),
    drop=st.one_of(st.none(), st.lists(st.one_of(st.text(), st.integers())))
)
def test_type_postcondition(d, keep, drop):
    result = subdict(d, keep, drop)
    assert isinstance(result, dict)
    assert type(result) == type(d)


@given(
    d=st.dictionaries(keys=st.one_of(st.text(), st.integers()), values=st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.none())),
    keep=st.one_of(st.none(), st.lists(st.one_of(st.text(), st.integers()))),
    drop=st.one_of(st.none(), st.lists(st.one_of(st.text(), st.integers())))
)
def test_invariant_preservation_keys_subset(d, keep, drop):
    result = subdict(d, keep, drop)
    assert set(result.keys()).issubset(set(d.keys()))


@given(
    d=st.dictionaries(keys=st.one_of(st.text(), st.integers()), values=st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.none())),
    keep=st.one_of(st.none(), st.lists(st.one_of(st.text(), st.integers()))),
    drop=st.one_of(st.none(), st.lists(st.one_of(st.text(), st.integers())))
)
def test_invariant_preservation_values_match(d, keep, drop):
    result = subdict(d, keep, drop)
    assert all(result[k] == d[k] for k in result)


@given(
    d=st.dictionaries(keys=st.one_of(st.text(), st.integers()), values=st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.none())),
    keep=st.one_of(st.none(), st.lists(st.one_of(st.text(), st.integers()))),
    drop=st.lists(st.one_of(st.text(), st.integers()), min_size=1)
)
def test_value_postcondition_drop(d, keep, drop):
    result = subdict(d, keep, drop)
    assert all(k not in result for k in drop)


@given(
    d=st.dictionaries(keys=st.one_of(st.text(), st.integers()), values=st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.none())),
    keep=st.lists(st.one_of(st.text(), st.integers())),
    drop=st.one_of(st.none(), st.lists(st.one_of(st.text(), st.integers())))
)
def test_value_postcondition_keep(d, keep, drop):
    result = subdict(d, keep, drop)
    drop_set = set(drop) if drop is not None else set()
    assert all(k in result for k in keep if k in d and k not in drop_set)


@given(
    d=st.dictionaries(keys=st.one_of(st.text(), st.integers()), values=st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.none())),
    keep=st.one_of(st.none(), st.lists(st.one_of(st.text(), st.integers()))),
    drop=st.one_of(st.none(), st.lists(st.one_of(st.text(), st.integers())))
)
def test_idempotence(d, keep, drop):
    first = subdict(d, keep, drop)
    second = subdict(first, keep, drop)
    assert second == first


@given(
    d=st.dictionaries(keys=st.one_of(st.text(), st.integers()), values=st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.none())),
    keep=st.one_of(st.none(), st.lists(st.one_of(st.text(), st.integers()))),
    drop=st.one_of(st.none(), st.lists(st.one_of(st.text(), st.integers()))),
    extra=st.lists(st.one_of(st.text(), st.integers()))
)
def test_metamorphic_superset_keep(d, keep, drop, extra):
    # keep2 is a superset of keep
    keep2 = (keep if keep is not None else []) + extra
    result_keep = set(subdict(d, keep, drop).keys())
    result_keep2 = set(subdict(d, keep2, drop).keys())
    assert result_keep == result_keep & result_keep2


@given(
    d=st.dictionaries(keys=st.one_of(st.text(), st.integers()), values=st.one_of(st.integers(), st.text(), st.floats(allow_nan=False), st.none())),
    keep=st.one_of(st.none(), st.lists(st.one_of(st.text(), st.integers()))),
    drop=st.one_of(st.none(), st.lists(st.one_of(st.text(), st.integers())))
)
def test_totality(d, keep, drop):
    # Should not raise for any valid inputs
    subdict(d, keep, drop)

from hypothesis import given, strategies as st
import pytest


def format_histogram_counts(bin_counts, width=None, format_bin=None):
    """The formatting logic behind :meth:`Stats.format_histogram`, which
    takes the output of :meth:`Stats.get_histogram_counts`, and passes
    them to this function.

    Args:
        bin_counts (list): A list of bin values to counts.
        width (int): Number of character columns in the text output,
            defaults to 80 or console width in Python 3.3+.
        format_bin (callable): Used to convert bin values into string
            labels.
    """
    lines = []
    if not format_bin:
        format_bin = lambda v: v
    if not width:
        try:
            import shutil
            width = shutil.get_terminal_size()[0]
        except Exception:
            width = 80
    bins = [b for b, _ in bin_counts]
    count_max = max([count for _, count in bin_counts])
    count_cols = len(str(count_max))
    labels = ['%s' % format_bin(b) for b in bins]
    label_cols = max([len(l) for l in labels])
    tmp_line = '{}: {} #'.format('x' * label_cols, count_max)
    bar_cols = max(width - len(tmp_line), 3)
    line_k = float(bar_cols) / count_max
    tmpl = '{label:>{label_cols}}: {count:>{count_cols}} {bar}'
    for label, (bin_val, count) in zip(labels, bin_counts):
        bar_len = int(round(count * line_k))
        bar = '#' * bar_len or '|'
        line = tmpl.format(label=label, label_cols=label_cols, count=count, count_cols=count_cols, bar=bar)
        lines.append(line)
    return '\n'.join(lines)


@given(
    bin_counts=st.lists(
        st.tuples(
            st.one_of(st.integers(), st.floats(allow_nan=False), st.text(max_size=10)),
            st.integers(min_value=1, max_value=10000)
        ),
        min_size=1, max_size=20
    ),
    width=st.one_of(st.none(), st.integers(min_value=10, max_value=200)),
    format_bin=st.one_of(st.none(), st.just(str), st.just(repr), st.just(lambda x: f'bin:{x}'))
)
def test_type_postcondition(bin_counts, width, format_bin):
    result = format_histogram_counts(bin_counts, width, format_bin)
    assert isinstance(result, str)


@given(
    bin_counts=st.lists(
        st.tuples(
            st.one_of(st.integers(), st.floats(allow_nan=False), st.text(max_size=10)),
            st.integers(min_value=1, max_value=10000)
        ),
        min_size=1, max_size=20
    ),
    width=st.one_of(st.none(), st.integers(min_value=10, max_value=200)),
    format_bin=st.one_of(st.none(), st.just(str), st.just(repr), st.just(lambda x: f'bin:{x}'))
)
def test_value_postcondition(bin_counts, width, format_bin):
    result = format_histogram_counts(bin_counts, width, format_bin)
    assert result.count('\n') == len(bin_counts) - 1


@given(
    bin_counts=st.lists(
        st.tuples(
            st.one_of(st.integers(), st.floats(allow_nan=False), st.text(max_size=10)),
            st.integers(min_value=1, max_value=10000)
        ),
        min_size=1, max_size=20
    ),
    width=st.one_of(st.none(), st.integers(min_value=10, max_value=200)),
    format_bin=st.one_of(st.none(), st.just(str), st.just(repr), st.just(lambda x: f'bin:{x}'))
)
def test_invariant_preservation(bin_counts, width, format_bin):
    result = format_histogram_counts(bin_counts, width, format_bin)
    assert len(result.splitlines()) == len(bin_counts)


@given(
    bin_counts=st.lists(
        st.tuples(
            st.one_of(st.integers(), st.floats(allow_nan=False), st.text(max_size=10)),
            st.integers(min_value=1, max_value=10000)
        ),
        min_size=1, max_size=20
    ),
    width1=st.integers(min_value=10, max_value=200),
)
def test_metamorphic(bin_counts, width1):
    # Same width must always produce identical output (deterministic)
    result_a = format_histogram_counts(bin_counts, width1)
    result_b = format_histogram_counts(bin_counts, width1)
    assert result_a == result_b


@given(
    bin_counts=st.lists(
        st.tuples(
            st.one_of(st.integers(), st.floats(allow_nan=False), st.text(max_size=10)),
            st.integers(min_value=1, max_value=10000)
        ),
        min_size=1, max_size=20
    )
)
def test_totality(bin_counts):
    # Should not raise for any valid non-empty list of (bin, count) pairs
    format_histogram_counts(bin_counts)

from hypothesis import given, strategies as st
import pytest


def under2camel(under_string):
    """Converts an underscored string to camelcased. Useful for turning a
    function name into a class name.

    >>> under2camel('complex_tokenizer')
    'ComplexTokenizer'
    """
    return ''.join((w.capitalize() or '_' for w in under_string.split('_')))


@given(under_string=st.from_regex(r'[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*', fullmatch=True))
def test_type_postcondition(under_string):
    assert isinstance(under2camel(under_string), str)


@given(under_string=st.from_regex(r'[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*', fullmatch=True))
def test_value_postcondition_first_char_upper(under_string):
    result = under2camel(under_string)
    assert result[0].isupper()


@given(under_string=st.from_regex(r'[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*', fullmatch=True))
def test_value_postcondition_no_underscore(under_string):
    result = under2camel(under_string)
    assert '_' not in result


@given(under_string=st.from_regex(r'[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*', fullmatch=True))
def test_metamorphic_lowercase(under_string):
    assert under2camel(under_string.lower()) == under2camel(under_string)


@given(under_string=st.from_regex(r'[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*', fullmatch=True))
def test_invariant_preservation_length(under_string):
    result = under2camel(under_string)
    assert len(result.replace('_', '')) == len(under_string.replace('_', ''))


@given(under_string=st.from_regex(r'[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*', fullmatch=True))
def test_idempotence(under_string):
    once = under2camel(under_string)
    twice = under2camel(once)
    assert twice == once

from hypothesis import given, strategies as st
import pytest


def unwrap_text(text, ending='\n\n'):
    """
    Unwrap text, the natural complement to :func:`textwrap.wrap`.

    >>> text = "Short \\n lines  \\nwrapped\\nsmall.\\n\\nAnother\\nparagraph."
    >>> unwrap_text(text)
    'Short lines wrapped small.\\n\\nAnother paragraph.'

    Args:
       text: A string to unwrap.
       ending (str): The string to join all unwrapped paragraphs
          by. Pass ``None`` to get the list. Defaults to '\\n\\n' for
          compatibility with Markdown and RST.

    """
    all_grafs = []
    cur_graf = []
    for line in text.splitlines():
        line = line.strip()
        if line:
            cur_graf.append(line)
        else:
            all_grafs.append(' '.join(cur_graf))
            cur_graf = []
    if cur_graf:
        all_grafs.append(' '.join(cur_graf))
    if ending is None:
        return all_grafs
    return ending.join(all_grafs)


@given(text=st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=500))
def test_idempotence(text):
    assert unwrap_text(unwrap_text(text)) == unwrap_text(text)


@given(text=st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=500))
def test_metamorphic(text):
    assert unwrap_text(text) == unwrap_text(text.replace('\n', ' \n '))


@given(text=st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=500))
def test_invariant_preservation(text):
    # Count non-empty paragraph blocks in the original text
    original_grafs = [block for block in text.split('\n\n') if any(line.strip() for line in block.splitlines())]
    result = unwrap_text(text)
    # Count paragraphs in the result (split by the default ending '\n\n')
    result_grafs = [block for block in result.split('\n\n') if block.strip()]
    assert len(result_grafs) == len(original_grafs)


@given(
    text=st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=500),
    ending=st.one_of(st.none(), st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=20))
)
def test_type_postcondition(text, ending):
    result = unwrap_text(text, ending)
    if ending is not None:
        assert isinstance(result, str)
    else:
        assert isinstance(result, list)


@given(
    text=st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=500),
    ending=st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=20)
)
def test_value_postcondition(text, ending):
    result = unwrap_text(text, ending)
    # No intra-paragraph newlines survive unless the ending itself contains '\n\n'
    if '\n\n' not in ending:
        assert '\n\n' not in result

