@given(number=st.integers(), k=st.integers(min_value=1, max_value=1000))
def test_metamorphic_plus_100(number, k):
    shifted = number + k * 100
    n_mod = abs(int(number)) % 100
    s_mod = abs(int(shifted)) % 100
    if n_mod not in (11, 12, 13) and s_mod not in (11, 12, 13):
        assert ordinal(number) == ordinal(shifted)


@given(number=st.integers())
