from hypothesis import given, strategies as st
import pytest
import types
import itertools


def mro_items(type_obj):
    """Takes a type and returns an iterator over all class variables
    throughout the type hierarchy (respecting the MRO).

    >>> sorted(set([k for k, v in mro_items(int) if not k.startswith('__') and 'bytes' not in k and not callable(v)]))
    ['denominator', 'imag', 'numerator', 'real']
    """
    import itertools
    return itertools.chain.from_iterable((ct.__dict__.items() for ct in type_obj.__mro__))


@given(type_obj=st.sampled_from([int, str, float, bool, list, dict, tuple, set, bytes, bytearray, object, type, Exception, ValueError, TypeError, KeyError, IndexError, AttributeError, RuntimeError, StopIteration, BaseException]))
def test_type_postcondition(type_obj):
    result = mro_items(type_obj)
    assert hasattr(result, '__iter__') and hasattr(result, '__next__')


@given(type_obj=st.sampled_from([int, str, float, bool, list, dict, tuple, set, bytes, bytearray, object, type, Exception, ValueError, TypeError, KeyError, IndexError, AttributeError, RuntimeError, StopIteration, BaseException]))
def test_invariant_preservation_mro_superset(type_obj):
    # Only test types that have a non-trivial base (i.e., base is not itself)
    if not type_obj.__bases__ or type_obj.__bases__[0] is type_obj:
        return
    base = type_obj.__bases__[0]
    keys_type = set(k for k, v in mro_items(type_obj))
    keys_base = set(k for k, v in mro_items(base))
    assert keys_type.issuperset(keys_base)


