    result = partial_ordering(cls)
    assert result is cls


@given(cls=st.one_of(
    st.just(type('FullOrdered', (), {
        '__le__': lambda self, other: NotImplemented,
        '__ge__': lambda self, other: NotImplemented,
        '__lt__': lambda self, other: NotImplemented,
        '__gt__': lambda self, other: NotImplemented,
        '__eq__': lambda self, other: NotImplemented,
    })),
))
def test_invariant_preservation_existing_methods(cls):
    original_lt = cls.__lt__
    original_gt = cls.__gt__
    original_eq = cls.__eq__
    decorated = partial_ordering(cls)
    assert decorated.__lt__ is original_lt
    assert decorated.__gt__ is original_gt
    assert decorated.__eq__ is original_eq


@given(cls=st.one_of(
    st.just(type('MinimalOrdered', (), {
        '__le__': lambda self, other: NotImplemented,
        '__ge__': lambda self, other: NotImplemented,
    })),
