    st.builds(
        lambda: (lambda cls: cls)(type('AlreadyDecorated', (), {
            '__le__': lambda self, other: NotImplemented,
            '__ge__': lambda self, other: NotImplemented,
        }))
    ),
))
def test_value_postcondition_le_ge_untouched(cls):
    original_le = cls.__le__
    original_ge = cls.__ge__
    decorated = partial_ordering(cls)
    assert decorated.__le__ is original_le
