from hypothesis import given, strategies as st
import pytest
import types


def rstrip_iter(iterable, strip_value=None):
    """Strips values from the end of an iterable. Stripped items will
    match the value of the argument strip_value. Functionality is analogous
    to that of the method str.rstrip. Returns a generator.

    >>> list(rstrip_iter(['Foo', 'Bar', 'Bam'], 'Bam'))
    ['Foo', 'Bar']

    """
    iterator = iter(iterable)
    for i in iterator:
        if i == strip_value:
            cache = list()
            cache.append(i)
            broken = False
            for i in iterator:
                if i == strip_value:
                    cache.append(i)
                else:
                    broken = True
                    break
            if not broken:
                return
            yield from cache
        yield i


@given(iterable=st.lists(st.integers(min_value=0, max_value=5)), strip_value=st.integers(min_value=0, max_value=5))
def test_idempotence(iterable, strip_value):
    once = list(rstrip_iter(iterable, strip_value))
    twice = list(rstrip_iter(rstrip_iter(iterable, strip_value), strip_value))
    assert twice == once


@given(iterable=st.lists(st.integers(min_value=0, max_value=5)), strip_value=st.integers(min_value=0, max_value=5))
def test_invariant_preservation(iterable, strip_value):
    result = list(rstrip_iter(iterable, strip_value))
    n = len(result)
    # result must be a prefix of iterable
    assert result == iterable[:n]


@given(iterable=st.lists(st.integers(min_value=0, max_value=5)), strip_value=st.integers(min_value=0, max_value=5))
def test_value_postcondition_last_element(iterable, strip_value):
    result = list(rstrip_iter(iterable, strip_value))
    if result:
        assert result[-1] != strip_value


@given(iterable=st.lists(st.integers(min_value=0, max_value=5)), strip_value=st.integers(min_value=0, max_value=5))
def test_value_postcondition_length(iterable, strip_value):
    result = list(rstrip_iter(iterable, strip_value))
    assert len(result) <= len(iterable)


@given(iterable=st.lists(st.integers(min_value=0, max_value=5)), strip_value=st.integers(min_value=0, max_value=5))
def test_type_postcondition(iterable, strip_value):
    assert isinstance(rstrip_iter(iterable, strip_value), types.GeneratorType)


@given(iterable=st.lists(st.integers(min_value=0, max_value=5)), strip_value=st.integers(min_value=0, max_value=5))
def test_metamorphic(iterable, strip_value):
    result_appended = list(rstrip_iter(iterable + [strip_value], strip_value))
    result_original = list(rstrip_iter(iterable, strip_value))
    assert result_appended == result_original

from hypothesis import given, strategies as st
import pytest
import math


def floor(x, options=None):
    """Return the floor of *x*. If *options* is set, return the largest
    integer or float from *options* that is less than or equal to
    *x*.

    Args:
        x (int or float): Number to be tested.
        options (iterable): Optional iterable of arbitrary numbers
          (ints or floats).

    >>> VALID_CABLE_CSA = [1.5, 2.5, 4, 6, 10, 25, 35, 50]
    >>> floor(3.5, options=VALID_CABLE_CSA)
    2.5
    >>> floor(2.5, options=VALID_CABLE_CSA)
    2.5

    """
    from math import floor as _floor
    import bisect
    if options is None:
        return _floor(x)
    options = sorted(options)
    i = bisect.bisect_right(options, x)
    if not i:
        raise ValueError('no floor options less than or equal to: %r' % x)
    return options[i - 1]


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)))
def test_idempotence(x):
    result = floor(x)
    assert floor(result) == result


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)))
def test_value_postcondition_floor_leq_x(x):
    assert floor(x) <= x


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)))
def test_value_postcondition_floor_returns_int(x):
    result = floor(x)
    assert isinstance(result, int)


@given(
    x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)),
    opts=st.lists(st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)), min_size=1)
)
def test_value_postcondition_floor_in_opts(x, opts):
    # Filter out NaN values from opts just in case, and ensure at least one option <= x
    clean_opts = [v for v in opts if not (isinstance(v, float) and math.isnan(v))]
    valid_opts = [v for v in clean_opts if v <= x]
    if not valid_opts:
        pytest.skip('no options <= x')
    result = floor(x, options=clean_opts)
    assert result in clean_opts


@given(
    x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)),
    opts=st.lists(st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)), min_size=1)
)
def test_value_postcondition_floor_opts_leq_x_and_largest(x, opts):
    clean_opts = [v for v in opts if not (isinstance(v, float) and math.isnan(v))]
    valid_opts = [v for v in clean_opts if v <= x]
    if not valid_opts:
        pytest.skip('no options <= x')
    result = floor(x, options=clean_opts)
    assert result <= x
    # Every option that is > result must also be > x (i.e., result is the largest option <= x)
    for v in clean_opts:
        assert v > x or v <= result


@given(
    x1=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)),
    x2=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False))
)
def test_metamorphic_monotonicity_no_options(x1, x2):
    a, b = (x1, x2) if x1 <= x2 else (x2, x1)
    assert floor(a) <= floor(b)


@given(
    x1=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)),
    x2=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)),
    opts=st.lists(st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)), min_size=1)
)
def test_metamorphic_monotonicity_with_options(x1, x2, opts):
    clean_opts = [v for v in opts if not (isinstance(v, float) and math.isnan(v))]
    a, b = (x1, x2) if x1 <= x2 else (x2, x1)
    valid_for_a = [v for v in clean_opts if v <= a]
    valid_for_b = [v for v in clean_opts if v <= b]
    if not valid_for_a or not valid_for_b:
        pytest.skip('no options <= one of the x values')
    assert floor(a, options=clean_opts) <= floor(b, options=clean_opts)


@given(x=st.one_of(st.integers(), st.floats(allow_nan=False, allow_infinity=False)))
def test_totality(x):
    # Should not raise for any int or float without options
    floor(x)

from hypothesis import given, strategies as st
import pytest


def a10n(string):
    """That thing where "internationalization" becomes "i18n", what's it
    called? Abbreviation? Oh wait, no: ``a10n``. (It's actually a form
    of `numeronym`_.)

    >>> a10n('abbreviation')
    'a10n'
    >>> a10n('internationalization')
    'i18n'
    >>> a10n('')
    ''

    .. _numeronym: http://en.wikipedia.org/wiki/Numeronym
    """
    if len(string) < 3:
        return string
    return f'{string[0]}{len(string[1:-1])}{string[-1]}'


@given(string=st.text())
def test_type_postcondition(string):
    assert isinstance(a10n(string), str)


@given(string=st.text())
def test_value_postcondition_length(string):
    assert len(a10n(string)) <= len(string)


@given(string=st.text().filter(lambda s: len(s) < 3))
def test_value_postcondition_short_strings(string):
    assert a10n(string) == string


@given(string=st.text().filter(lambda s: len(s) >= 3))
def test_invariant_preservation_first_last_chars(string):
    result = a10n(string)
    assert result[0] == string[0] and result[-1] == string[-1]


@given(string=st.text())
def test_totality(string):
    a10n(string)

