from hypothesis import given, strategies as st
import pytest


def args2cmd(args, sep=' '):
    """Return a shell-escaped string version of *args*, separated by
    *sep*, using the same rules as the Microsoft C runtime.

    >>> print(args2cmd(['aa', '[bb]', "cc'cc", 'dd"dd']))
    aa [bb] cc'cc dd\\"dd

    As you can see, escaping is through backslashing and not quoting,
    and double quotes are the only special character. See the comment
    in the code for more details. Based on internal code from the
    :mod:`subprocess` module.

    """
    '\n    1) Arguments are delimited by white space, which is either a\n       space or a tab.\n\n    2) A string surrounded by double quotation marks is\n       interpreted as a single argument, regardless of white space\n       contained within.  A quoted string can be embedded in an\n       argument.\n\n    3) A double quotation mark preceded by a backslash is\n       interpreted as a literal double quotation mark.\n\n    4) Backslashes are interpreted literally, unless they\n       immediately precede a double quotation mark.\n\n    5) If backslashes immediately precede a double quotation mark,\n       every pair of backslashes is interpreted as a literal\n       backslash.  If the number of backslashes is odd, the last\n       backslash escapes the next double quotation mark as\n       described in rule 3.\n\n    See http://msdn.microsoft.com/en-us/library/17w5ykft.aspx\n    or search http://msdn.microsoft.com for\n    "Parsing C++ Command-Line Arguments"\n    '
    result = []
    needquote = False
    for arg in args:
        bs_buf = []
        if result:
            result.append(' ')
        needquote = ' ' in arg or '\t' in arg or (not arg)
        if needquote:
            result.append('"')
        for c in arg:
            if c == '\\':
                bs_buf.append(c)
            elif c == '"':
                result.append('\\' * len(bs_buf) * 2)
                bs_buf = []
                result.append('\\"')
            else:
                if bs_buf:
                    result.extend(bs_buf)
                    bs_buf = []
                result.append(c)
        if bs_buf:
            result.extend(bs_buf)
        if needquote:
            result.extend(bs_buf)
            result.append('"')
    return ''.join(result)


@given(args=st.lists(st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=10), max_size=8), sep=st.text(min_size=1, max_size=3))
def test_type_postcondition(args, sep):
    assert isinstance(args2cmd(args, sep), str)


@given(
    a=st.text(alphabet=st.characters(blacklist_categories=('Cs',), blacklist_characters=(' ', '\t', '"', '\\')), min_size=1, max_size=10),
    b=st.text(alphabet=st.characters(blacklist_categories=('Cs',), blacklist_characters=(' ', '\t', '"', '\\')), min_size=1, max_size=10),
    c=st.text(alphabet=st.characters(blacklist_categories=('Cs',), blacklist_characters=(' ', '\t', '"', '\\')), min_size=1, max_size=10),
)
def test_metamorphic(a, b, c):
    # No arg needs quoting: no spaces, tabs, quotes, or backslashes
    combined = args2cmd([a, b, c])
    individual = args2cmd([a]) + ' ' + args2cmd([b]) + ' ' + args2cmd([c])
    assert combined == individual


@given(args=st.lists(st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=10), max_size=8), sep=st.text(min_size=1, max_size=3))
def test_totality(args, sep):
    # Should not raise for any valid input
    args2cmd(args, sep)

from hypothesis import given, strategies as st
import pytest
from boltons.iterutils import parse_int_list


def format_int_list(int_list, delim=',', range_delim='-', delim_space=False):
    """Returns a sorted range string from a list of positive integers
    (*int_list*). Contiguous ranges of integers are collapsed to min
    and max values. Reverse of :func:`parse_int_list`.

    Args:
        int_list (list): List of positive integers to be converted
           into a range string (e.g. [1,2,4,5,6,8]).
        delim (char): Defaults to ','. Separates integers and
           contiguous ranges of integers.
        range_delim (char): Defaults to '-'. Indicates a contiguous
           range of integers.
        delim_space (bool): Defaults to ``False``. If ``True``, adds a
           space after all *delim* characters.

    >>> format_int_list([1,3,5,6,7,8,10,11,15])
    '1,3,5-8,10-11,15'

    """
    import collections
    output = []
    contig_range = collections.deque()
    for x in sorted(int_list):
        if len(contig_range) < 1:
            contig_range.append(x)
        elif len(contig_range) > 1:
            delta = x - contig_range[-1]
            if delta == 1:
                contig_range.append(x)
            elif delta > 1:
                range_substr = '{:d}{}{:d}'.format(min(contig_range), range_delim, max(contig_range))
                output.append(range_substr)
                contig_range.clear()
                contig_range.append(x)
            else:
                continue
        else:
            delta = x - contig_range[0]
            if delta == 1:
                contig_range.append(x)
            elif delta > 1:
                output.append(f'{contig_range.popleft():d}')
                contig_range.append(x)
            else:
                continue
    else:
        if len(contig_range) == 1:
            output.append(f'{contig_range.popleft():d}')
            contig_range.clear()
        elif len(contig_range) > 1:
            range_substr = '{:d}{}{:d}'.format(min(contig_range), range_delim, max(contig_range))
            output.append(range_substr)
            contig_range.clear()
    if delim_space:
        output_str = (delim + ' ').join(output)
    else:
        output_str = delim.join(output)
    return output_str


@given(int_list=st.lists(st.integers(min_value=1, max_value=10000), min_size=0, max_size=50))
def test_round_trip(int_list):
    assert parse_int_list(format_int_list(int_list)) == sorted(set(int_list))


@given(
    int_list=st.lists(st.integers(min_value=1, max_value=10000), min_size=0, max_size=50),
    delim=st.text(alphabet=st.characters(blacklist_categories=('Cs',), blacklist_characters=('-', '0123456789')), min_size=1, max_size=1),
    range_delim=st.text(alphabet=st.characters(blacklist_categories=('Cs',), blacklist_characters=(',', '0123456789')), min_size=1, max_size=1),
    delim_space=st.booleans(),
)
def test_type_postcondition(int_list, delim, range_delim, delim_space):
    assert isinstance(format_int_list(int_list, delim=delim, range_delim=range_delim, delim_space=delim_space), str)


@given(x=st.integers(min_value=1, max_value=10000))
def test_value_postcondition(x):
    assert str(x) in format_int_list([x])


@given(int_list=st.lists(st.integers(min_value=1, max_value=10000), min_size=0, max_size=50))
def test_metamorphic(int_list):
    result_original = format_int_list(int_list)
    result_sorted = format_int_list(sorted(int_list))
    result_deduped = format_int_list(list(set(int_list)))
    assert result_original == result_sorted
    assert result_original == result_deduped


@given(
    int_list=st.lists(st.integers(min_value=1, max_value=10000), min_size=0, max_size=50),
    extra=st.integers(min_value=1, max_value=10000),
)
def test_invariant_preservation(int_list, extra):
    if extra in int_list:
        return
    result_without = format_int_list(int_list)
    result_with = format_int_list(int_list + [extra])
    assert len(result_without) <= len(result_with)

from hypothesis import given, strategies as st
import pytest
import gzip


def gunzip_bytes(bytestring):
    """The :mod:`gzip` module is great if you have a file or file-like
    object, but what if you just have bytes. StringIO is one
    possibility, but it's often faster, easier, and simpler to just
    use this one-liner. Use this tried-and-true utility function to
    decompress gzip from bytes.

    >>> gunzip_bytes(_EMPTY_GZIP_BYTES) == b''
    True
    >>> gunzip_bytes(_NON_EMPTY_GZIP_BYTES).rstrip() == b'bytesahoy!'
    True
    """
    import zlib
    return zlib.decompress(bytestring, 16 + zlib.MAX_WBITS)


@given(data=st.binary())
def test_round_trip(data):
    import gzip
    compressed = gzip.compress(data)
    assert gunzip_bytes(compressed) == data


@given(bytestring=st.binary().map(lambda b: __import__('gzip').compress(b)))
def test_type_postcondition(bytestring):
    assert isinstance(gunzip_bytes(bytestring), bytes)


@given(bytestring=st.binary().map(lambda b: __import__('gzip').compress(b)))
def test_value_postcondition(bytestring):
    assert len(gunzip_bytes(bytestring)) >= 0


@given(bytestring=st.binary().map(lambda b: __import__('gzip').compress(b)))
def test_totality(bytestring):
    gunzip_bytes(bytestring)

from hypothesis import given, strategies as st
import pytest
import typing


def human_readable_list(items: typing.Sequence[str], delimiter: str=',', conjunction: str='and', *, oxford: bool=True) -> str:
    """
    Given a list of strings, return a human readable string with
    appropriate delimiters and the conjunction word.

    Args:
        items: The list of strings to join.
        delimiter (optional): The delimiter to use between items.
        conjunction (optional): The word to use before the last item.
        oxford (optional): Whether to use the Oxford comma/delimiter before
            the conjunction in lists of 3+ items.

    Returns:
        str: The human readable string.
    """
    if not items:
        return ''
    delimiter = delimiter and delimiter.strip() + ' '
    conjunction = conjunction.strip()
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f'{items[0]} {conjunction} {items[1]}'
    return f'{delimiter.join(items[:-1])}{(delimiter if oxford else ' ')}{conjunction} {items[-1]}'


@given(items=st.one_of(st.just([]), st.lists(st.text(), min_size=1, max_size=10)))
def test_type_postcondition(items):
    assert isinstance(human_readable_list(items), str)


