def test_value_postcondition_all_items_present(items):
    result = human_readable_list(items)
    assert all(item in result for item in items)


@given(items=st.just([]))
def test_value_postcondition_empty(items):
    assert human_readable_list(items) == ''


@given(s=st.text())
def test_value_postcondition_single_element(s):
    assert human_readable_list([s]) == s


@given(
    items=st.lists(st.text(), min_size=2, max_size=10),
    conjunction=st.text(min_size=1, max_size=10),
)
def test_metamorphic_conjunction_present(items, conjunction):
    result = human_readable_list(items, conjunction=conjunction)
    assert conjunction.strip() in result


@given(
    items=st.lists(st.text(), min_size=1, max_size=9),
    extra_item=st.text(min_size=1, max_size=10),
    delimiter=st.text(min_size=1, max_size=5),
    conjunction=st.text(min_size=1, max_size=10),
    oxford=st.booleans(),
)
def test_metamorphic_longer_with_extra_item(items, extra_item, delimiter, conjunction, oxford):
    result_base = human_readable_list(items, delimiter=delimiter, conjunction=conjunction, oxford=oxford)
    result_extended = human_readable_list(items + [extra_item], delimiter=delimiter, conjunction=conjunction, oxford=oxford)
    assert len(result_extended) > len(result_base)


@given(
    items=st.one_of(st.just([]), st.lists(st.text(), min_size=1, max_size=10)),
    delimiter=st.text(min_size=1, max_size=5),
    conjunction=st.text(min_size=1, max_size=10),
    oxford=st.booleans(),
)
def test_totality(items, delimiter, conjunction, oxford):
    human_readable_list(items, delimiter=delimiter, conjunction=conjunction, oxford=oxford)

