from hypothesis import given, strategies as st
import pytest
from boltons.strutils import format_int_list


def parse_int_list(range_string, delim=',', range_delim='-'):
    """Returns a sorted list of positive integers based on
    *range_string*. Reverse of :func:`format_int_list`.

    Args:
        range_string (str): String of comma separated positive
            integers or ranges (e.g. '1,2,4-6,8'). Typical of a custom
            page range string used in printer dialogs.
        delim (char): Defaults to ','. Separates integers and
            contiguous ranges of integers.
        range_delim (char): Defaults to '-'. Indicates a contiguous
            range of integers.

    >>> parse_int_list('1,3,5-8,10-11,15')
    [1, 3, 5, 6, 7, 8, 10, 11, 15]

    """
    output = []
    for x in range_string.strip().split(delim):
        if range_delim in x:
            range_limits = list(map(int, x.split(range_delim)))
            output += list(range(min(range_limits), max(range_limits) + 1))
        elif not x:
            continue
        else:
            output.append(int(x))
    return sorted(output)


@given(lst=st.lists(st.integers(min_value=1, max_value=1000), min_size=0, max_size=20).map(lambda l: sorted(set(l))))
def test_round_trip(lst):
    assert parse_int_list(format_int_list(lst)) == lst


@given(range_string=st.lists(st.integers(min_value=1, max_value=1000), min_size=0, max_size=20).map(lambda lst: ','.join(str(x) for x in sorted(set(lst)))))
def test_type_postcondition(range_string):
    result = parse_int_list(range_string)
    assert isinstance(result, list) and all(isinstance(x, int) for x in result)


@given(range_string=st.lists(st.integers(min_value=1, max_value=1000), min_size=0, max_size=20).map(lambda lst: ','.join(str(x) for x in sorted(set(lst)))))
def test_value_postcondition(range_string):
    result = parse_int_list(range_string)
    assert result == sorted(result) and all(x > 0 for x in result)


@given(
    range_string=st.lists(st.integers(min_value=1, max_value=1000), min_size=0, max_size=20).map(lambda lst: ','.join(str(x) for x in sorted(set(lst)))),
    delim=st.sampled_from([';', '|', '/'])
)
def test_metamorphic(range_string, delim):
    # Replace the default ',' delimiter with a custom one
    custom_range_string = range_string.replace(',', delim)
    assert parse_int_list(custom_range_string, delim=delim) == parse_int_list(range_string, delim=',')


@given(lst=st.lists(st.integers(min_value=1, max_value=1000), min_size=0, max_size=20).map(lambda l: sorted(set(l))))
def test_invariant_preservation(lst):
    assert set(parse_int_list(format_int_list(lst))) == set(lst)

from hypothesis import given, strategies as st
import pytest


def removeprefix(text: str, prefix: str) -> str:
    """
    Remove `prefix` from start of `text` if present.

    Backport of `str.removeprefix` for Python versions less than 3.9.

    Args:
        text: A string to remove the prefix from.
        prefix: The string to remove from the beginning of `text`.
    """
    if text.startswith(prefix):
        return text[len(prefix):]
    return text


@given(text=st.text(), prefix=st.text())
def test_idempotence(text, prefix):
    assert removeprefix(removeprefix(text, prefix), prefix) == removeprefix(text, prefix)


