    baseclass=st.one_of(st.from_type(type), st.integers(), st.text(), st.floats(allow_nan=False), st.booleans(), st.none(), st.binary(), st.just(int), st.just(str), st.just(float), st.just(bool), st.just(list), st.just(dict), st.just(object)),
