    issubclass(subclass, baseclass)


@given(
    A=st.one_of(st.from_type(type), st.just(int), st.just(str), st.just(float), st.just(bool), st.just(list), st.just(dict), st.just(object)),
    B=st.one_of(st.from_type(type), st.just(int), st.just(str), st.just(float), st.just(bool), st.just(list), st.just(dict), st.just(object)),
    C=st.one_of(st.from_type(type), st.just(int), st.just(str), st.just(float), st.just(bool), st.just(list), st.just(dict), st.just(object)),
)
def test_metamorphic_transitivity(A, B, C):
    # If A is a subclass of B and B is a subclass of C, then A must be a subclass of C
    if issubclass(A, B) and issubclass(B, C):
        assert issubclass(A, C)

