from hypothesis import given, strategies as st
import pytest


def resolve_path_parts(path_parts):
    """Normalize the URL path by resolving segments of '.' and '..',
    resulting in a dot-free path.  See RFC 3986 section 5.2.4, Remove
    Dot Segments.
    """
    ret = []
    for part in path_parts:
        if part == '.':
            pass
        elif part == '..':
            if ret and (len(ret) > 1 or ret[0]):
                ret.pop()
        else:
            ret.append(part)
    if list(path_parts[-1:]) in (['.'], ['..']):
        ret.append('')
    return ret


@given(path_parts=st.lists(st.one_of(st.just('.'), st.just('..'), st.text(alphabet=st.characters(blacklist_characters='/'), min_size=1)), min_size=1))
def test_idempotence(path_parts):
    first = resolve_path_parts(path_parts)
    assert resolve_path_parts(first) == first


@given(path_parts=st.lists(st.one_of(st.just('.'), st.just('..'), st.text(alphabet=st.characters(blacklist_characters='/'), min_size=1)), min_size=1))
def test_value_postcondition(path_parts):
    result = resolve_path_parts(path_parts)
    assert '.' not in result and '..' not in result


@given(path_parts=st.lists(st.one_of(st.just('.'), st.just('..'), st.text(alphabet=st.characters(blacklist_characters='/'), min_size=1)), min_size=1))
def test_invariant_preservation(path_parts):
    result = resolve_path_parts(path_parts)
    assert len(result) <= len(path_parts)


@given(path_parts=st.lists(st.one_of(st.just('.'), st.just('..'), st.text(alphabet=st.characters(blacklist_characters='/'), min_size=1)), min_size=1))
def test_type_postcondition(path_parts):
    assert isinstance(resolve_path_parts(path_parts), list)


@given(path_parts=st.lists(st.one_of(st.just('.'), st.just('..'), st.text(alphabet=st.characters(blacklist_characters='/'), min_size=1)), min_size=1))
def test_totality(path_parts):
    resolve_path_parts(path_parts)

from hypothesis import given, strategies as st
import pytest
from inflection import underscore


def camelize(string: str, uppercase_first_letter: bool=True) -> str:
    """
    Convert strings to CamelCase.

    Examples::

        >>> camelize("device_type")
        'DeviceType'
        >>> camelize("device_type", False)
        'deviceType'

    :func:`camelize` can be thought of as a inverse of :func:`underscore`,
    although there are some cases where that does not hold::

        >>> camelize(underscore("IOError"))
        'IoError'

    :param uppercase_first_letter: if set to `True` :func:`camelize` converts
        strings to UpperCamelCase. If set to `False` :func:`camelize` produces
        lowerCamelCase. Defaults to `True`.
    """
    import re
    if uppercase_first_letter:
        return re.sub('(?:^|_)(.)', lambda m: m.group(1).upper(), string)
    else:
        return string[0].lower() + camelize(string)[1:]


@given(string=st.from_regex(r'[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*', fullmatch=True))
def test_round_trip(string):
    from inflection import underscore
    assert underscore(camelize(string)) == string


@given(string=st.one_of(st.from_regex(r'[A-Z][a-zA-Z0-9]*', fullmatch=True), st.from_regex(r'[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*', fullmatch=True)))
def test_idempotence(string):
    assert camelize(camelize(string, True), True) == camelize(string, True)


@given(string=st.one_of(st.just(''), st.from_regex(r'[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*', fullmatch=True), st.from_regex(r'[A-Z][a-zA-Z0-9]*([A-Z][a-zA-Z0-9]*)*', fullmatch=True), st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'))), uppercase_first_letter=st.booleans())
def test_type_postcondition(string, uppercase_first_letter):
    assert isinstance(camelize(string, uppercase_first_letter), str)


@given(string=st.from_regex(r'[a-zA-Z][a-zA-Z0-9]*(_[a-z][a-z0-9]*)*', fullmatch=True))
def test_value_postcondition_upper(string):
    result = camelize(string, True)
    assert len(result) > 0
    assert result[0].isupper()


@given(string=st.from_regex(r'[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*', fullmatch=True))
def test_value_postcondition_lower(string):
    result = camelize(string, False)
    assert len(result) > 0
    assert result[0].islower()


@given(string=st.from_regex(r'[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*', fullmatch=True), uppercase_first_letter=st.booleans())
def test_metamorphic_no_underscore(string, uppercase_first_letter):
    assert '_' not in camelize(string, uppercase_first_letter)

from hypothesis import given, strategies as st
import pytest


def dasherize(word: str) -> str:
    """Replace underscores with dashes in the string.

    Example::

        >>> dasherize("puni_puni")
        'puni-puni'

    """
    return word.replace('_', '-')


@given(word=st.text())
def test_idempotence(word):
    assert dasherize(dasherize(word)) == dasherize(word)


@given(word=st.text())
def test_invariant_preservation(word):
    assert len(dasherize(word)) == len(word)


@given(word=st.text(), word2=st.text())
def test_metamorphic(word, word2):
    assert dasherize(word + word2) == dasherize(word) + dasherize(word2)


@given(word=st.text())
def test_value_postcondition(word):
    assert '_' not in dasherize(word)


@given(word=st.text())
def test_type_postcondition(word):
    assert isinstance(dasherize(word), str)

from hypothesis import given, strategies as st
import pytest


def humanize(word: str) -> str:
    """
    Capitalize the first word and turn underscores into spaces and strip a
    trailing ``"_id"``, if any. Like :func:`titleize`, this is meant for
    creating pretty output.

    Examples::

        >>> humanize("employee_salary")
        'Employee salary'
        >>> humanize("author_id")
        'Author'

    """
    import re
    word = re.sub('_id$', '', word)
    word = word.replace('_', ' ')
    word = re.sub('(?i)([a-z\\d]*)', lambda m: m.group(1).lower(), word)
    word = re.sub('^\\w', lambda m: m.group(0).upper(), word)
    return word


@given(word=st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'), min_size=0, max_size=50))
def test_idempotence(word):
    assert humanize(humanize(word)) == humanize(word)


@given(word=st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'), min_size=0, max_size=50))
def test_metamorphic(word):
    assert humanize(word.upper()) == humanize(word)
    assert humanize(word.lower()) == humanize(word)


@given(word=st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'), min_size=0, max_size=50))
def test_value_postcondition_first_char_upper(word):
    result = humanize(word)
    if result:
        assert result[0] == result[0].upper()


@given(word=st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'), min_size=0, max_size=50))
def test_value_postcondition_no_underscores(word):
    assert '_' not in humanize(word)


@given(word=st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'), min_size=0, max_size=50))
def test_value_postcondition_no_trailing_id(word):
    result = humanize(word)
    assert not result.endswith('_id')
    assert not result.endswith(' id')


@given(word=st.text(alphabet=st.sampled_from('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_'), min_size=0, max_size=50))
def test_type_postcondition(word):
    assert isinstance(humanize(word), str)

from hypothesis import given, strategies as st
import pytest


def transliterate(string: str) -> str:
    """
    Replace non-ASCII characters with an ASCII approximation. If no
    approximation exists, the non-ASCII character is ignored. The string must
    be ``unicode``.

    Examples::

        >>> transliterate('älämölö')
        'alamolo'
        >>> transliterate('Ærøskøbing')
        'rskbing'

    """
    import unicodedata
    normalized = unicodedata.normalize('NFKD', string)
    return normalized.encode('ascii', 'ignore').decode('ascii')


@given(string=st.text())
def test_idempotence(string):
    assert transliterate(transliterate(string)) == transliterate(string)


@given(string=st.text())
def test_invariant_preservation_ascii_ordinals(string):
    assert all(ord(c) < 128 for c in transliterate(string))


@given(string=st.text())
def test_invariant_preservation_length(string):
    assert len(transliterate(string)) <= len(string)


@given(s1=st.text(), s2=st.text())
def test_metamorphic(s1, s2):
    assert transliterate(s1 + s2) == transliterate(s1) + transliterate(s2)


@given(string=st.text())
def test_type_postcondition(string):
    assert isinstance(transliterate(string), str)


@given(string=st.text())
def test_value_postcondition(string):
    assert transliterate(string).isascii()

from hypothesis import given, strategies as st
import pytest


def trimcase(string):
    """Convert string into trimmed string.

    Args:
        string: String to convert.

    Returns:
        string: Trimmed case string
    """
    return str(string).strip()


@given(string=st.text())
def test_idempotence(string):
    assert trimcase(trimcase(string)) == trimcase(string)


@given(string=st.text())
def test_metamorphic(string):
    assert trimcase(string) == trimcase('   ' + string + '   ')


@given(string=st.text())
def test_value_postcondition(string):
    assert trimcase(string) == trimcase(string).strip()


@given(string=st.text())
def test_invariant_preservation(string):
    assert trimcase(string) in str(string)


@given(string=st.text())
def test_type_postcondition(string):
    assert isinstance(trimcase(string), str)
